313	// Plain before/after behavior through the public API: after a successful
314	// restore the first page reflects only the snapshot chain.
315	func TestQueryTxsBeforeAndAfterRestore(t *testing.T) {
316		index := buildRestoreQueryOldChain(t)
317	
318		before, err := index.QueryTxs(restoreTxQuery)
319		if err != nil {
320			t.Fatal(err)
321		}
322		if !reflect.DeepEqual(viewOf(before), viewOf(literalRestoreTxOldFirstPage())) {
323			t.Fatalf("pre-restore page=%+v, want old first page", before)
324		}
325	
326		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
327			t.Fatalf("restore refused: %v", err)
328		}
329		if index.Tip != 4 {
330			t.Fatalf("tip=%d, want restored tip 4", index.Tip)
331		}
332	
333		after, err := index.QueryTxs(restoreTxQuery)
334		if err != nil {
335			t.Fatal(err)
336		}
337		if !reflect.DeepEqual(viewOf(after), viewOf(literalRestoreTxNewFirstPage())) {
338			t.Fatalf("post-restore page not wholly on the new chain:\n%+v", after)
339		}
340		// No residue of the replaced chain: removed heights and hashes are gone,
341		// and no removed-height match leaks into the answer or the statistics.
342		for _, height := range []int64{5, 6} {
343			if _, ok := index.Blocks[height]; ok {
344				t.Fatalf("replaced height %d still present", height)
345			}
346		}
347		for _, gone := range []string{"h1", "h2", "h3", "h4", "h5", "h6"} {
348			if _, ok := index.ByHash[gone]; ok {
349				t.Fatalf("replaced hash %s still indexed", gone)
350			}
351		}
352		for _, hit := range after.Hits {
353			if hit.Height > 4 || strings.HasPrefix(hit.BlockHash, "h") {
354				t.Fatalf("removed-chain record leaked into post-restore page: %+v", hit)
355			}
356		}
357		if after.ToHeight != 4 || after.TotalMatches != 5 || after.MatchedBlocks != 2 {
358			t.Fatalf("old tip or statistics leaked into post-restore page: %+v", after)
359		}
360	}
