1	package indexroom
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// This file guards the MinBlocks threshold combined with a timestamp window
9	// against the reorg shape that is easiest to miss: the chain keeps the SAME
10	// height span, the SAME block hashes, the SAME parent links and the SAME
11	// ordered transaction lists at every height — only the timestamps of SOME
12	// blocks move. Nothing about the blocks' identity changes, yet the set of
13	// identifiers reaching MinBlocks flips, because qualification is counted over
14	// in-window blocks only. A fresh query (empty cursor) issued after such a
15	// reorg must re-judge qualification entirely by the NEW times: identifiers
16	// that lost their second in-window block must vanish completely, identifiers
17	// that gained one must appear with every in-window occurrence, and the
18	// whole-range statistics on every page must describe the new main chain —
19	// never a leftover of the pre-reorg qualification or counts.
20	//
21	// The window is [0, 100): start included, end excluded, MinBlocks = 2.
22	// Starting the window at zero is deliberate: h1's real timestamp of zero sits
23	// exactly at the included start and must count as a qualifying block on both
24	// chains, while h4's missing timestamp must never count (a missing time is
25	// not zero) and h6's timestamp equal to the window end must neither count
26	// toward qualification nor have its occurrences returned.
27	//
28	//	                   old time   new time   in window old -> new
29	//	h1 parent g  [old, old]   0          0     yes -> yes  (real zero at the included start, unchanged)
30	//	h2 parent h1 [old, old]  50        150     yes -> OUT  (old loses its second qualifying block)
31	//	h3 parent h2 [new, new] 150         40     OUT -> in   (new gains a qualifying block)
32	//	h4 parent h3 [new]      nil        nil     OUT -> OUT  (missing stays missing; never counts)
33	//	h5 parent h4 [new]       90         90     yes -> yes  (new's one in-window block on both chains)
34	//	h6 parent h5 [new]      100        100     OUT -> OUT  (equal to the excluded end; never counts)
35	//
36	// Qualification (threshold 2, in-window distinct blocks):
37	//
38	//	old: before {h1, h2} -> QUALIFIED;  after {h1} -> not qualified.
39	//	new: before {h5} -> not qualified;  after {h3, h5} -> QUALIFIED.
40	//	  (h4's nil and h6's end-equal 100 never help on either chain, and the
41	//	  duplicate inside h3 still counts as one block.)
42	//
43	// Old answer (range 1..6): h1 old@0, h1 old@1, h2 old@0, h2 old@1 = 4
44	// occurrences over 2 matched blocks (h1, h2), upper height 6.
45	// New answer (range 1..6): h3 new@0, h3 new@1, h5 new@0 = 3 occurrences over
46	// 2 matched blocks (h3, h5), upper height 6.
47	//
48	// The two answers share not a single record, and TotalMatches differs (4 vs
49	// 3), so any page that keeps pre-reorg qualification, pre-reorg counts, or
50	// stitches the two states together is observable. The pinned upper height
51	// stays 6 on both chains: the time filter shrinking the result set must never
52	// shrink ToHeight.
53	
54	const (
55		mbTwWindowStart = int64(0)
56		mbTwWindowEnd   = int64(100)
57		mbTwPageSize    = 2
58		mbTwMinBlocks   = 2
59	)
60	
61	func mbTwBlock(height int64, hash, parent string, txs []string, time *int64) Block {
62		return Block{Height: height, Hash: hash, Parent: parent, Txs: txs, Time: time}
63	}
64	
65	// mbTwOldChain is the main chain before the time-only reorg.
66	func mbTwOldChain() []Block {
67		return []Block{
68			mbTwBlock(1, "h1", "g", []string{"old", "old"}, intptr(0)),
69			mbTwBlock(2, "h2", "h1", []string{"old", "old"}, intptr(50)),
70			mbTwBlock(3, "h3", "h2", []string{"new", "new"}, intptr(150)),
71			mbTwBlock(4, "h4", "h3", []string{"new"}, nil),
72			mbTwBlock(5, "h5", "h4", []string{"new"}, intptr(90)),
73			mbTwBlock(6, "h6", "h5", []string{"new"}, intptr(100)),
74		}
75	}
76	
77	// mbTwBranch is the alternate branch handed to Reorg. It starts at height 2
78	// rooted at the retained h1 and keeps every hash, parent link and transaction
79	// list; only the h2 and h3 timestamps move (h2 50->150 leaves the window,
80	// h3 150->40 enters it).
81	func mbTwBranch() []Block {
82		return []Block{
83			mbTwBlock(2, "h2", "h1", []string{"old", "old"}, intptr(150)),
84			mbTwBlock(3, "h3", "h2", []string{"new", "new"}, intptr(40)),
85			mbTwBlock(4, "h4", "h3", []string{"new"}, nil),
86			mbTwBlock(5, "h5", "h4", []string{"new"}, intptr(90)),
87			mbTwBlock(6, "h6", "h5", []string{"new"}, intptr(100)),
88		}
89	}
90	
91	// mbTwNewChain is the complete main chain after the reorg: retained h1 plus
92	// the re-timed branch.
93	func mbTwNewChain() []Block {
94		chain := append([]Block{}, mbTwOldChain()[:1]...)
95		return append(chain, mbTwBranch()...)
96	}
97	
98	func buildMbTwOldChain(t *testing.T) *Index {
99		t.Helper()
100		index := New()
101		for _, b := range mbTwOldChain() {
102			if err := index.Append(b); err != nil {
103				t.Fatalf("setup append at %d: %v", b.Height, err)
104			}
105		}
106		return index
107	}
108	
109	func mbTwQuery() TxQuery {
110		return TxQuery{
111			TimeStart: intptr(mbTwWindowStart),
112			TimeEnd:   intptr(mbTwWindowEnd),
113			MinBlocks: mbTwMinBlocks,
114			PageSize:  mbTwPageSize,
115		}
116	}
117	
118	// Hand-derived complete answers; the guarantee rests on these literal
119	// records and counts, not on recomputation by the code under test.
120	func mbTwOldHits() []TxHit {
121		return []TxHit{
122			{Height: 1, BlockHash: "h1", TxID: "old", Position: 0},
123			{Height: 1, BlockHash: "h1", TxID: "old", Position: 1},
124			{Height: 2, BlockHash: "h2", TxID: "old", Position: 0},
125			{Height: 2, BlockHash: "h2", TxID: "old", Position: 1},
126		}
127	}
128	
129	func mbTwNewHits() []TxHit {
130		return []TxHit{
131			{Height: 3, BlockHash: "h3", TxID: "new", Position: 0},
132			{Height: 3, BlockHash: "h3", TxID: "new", Position: 1},
133			{Height: 5, BlockHash: "h5", TxID: "new", Position: 0},
134		}
135	}
136	
137	// The structural invariant the regression rests on: above the retained h1,
138	// the reorg changes timestamps only. Every height, hash, parent link and
139	// ordered transaction list is identical on the two chains, the tip stays 6,
140	// and exactly the two re-timed heights are reported as dropped.
141	func TestMinBlocksTimeWindowReorgFixtureMovesTimesOnly(t *testing.T) {
142		oldChain, newChain := mbTwOldChain(), mbTwNewChain()
143		if len(oldChain) != len(newChain) || len(oldChain) != 6 {
144			t.Fatalf("chain lengths old=%d new=%d, want 6/6", len(oldChain), len(newChain))
145		}
146		for i := range oldChain {
147			o, n := oldChain[i], newChain[i]
148			if o.Height != n.Height || o.Hash != n.Hash || o.Parent != n.Parent {
149				t.Fatalf("height %d identity changed: old={%d %s %s} new={%d %s %s}",
150					i+1, o.Height, o.Hash, o.Parent, n.Height, n.Hash, n.Parent)
151			}
152			if !reflect.DeepEqual(o.Txs, n.Txs) {
153				t.Fatalf("height %d transaction list changed: old=%v new=%v", o.Height, o.Txs, n.Txs)
154			}
155		}
156		// Per-height transition table, including the unchanged real-zero h1, the
157		// missing-on-both-chains h4 and the end-equal h6.
158		window := timeWindow{enabled: true, start: mbTwWindowStart, end: mbTwWindowEnd}
159		flips := map[int64]struct {
160			oldIn, newIn bool
161			oldTime      *int64
162			newTime      *int64
163		}{
164			1: {true, true, intptr(0), intptr(0)},
165			2: {true, false, intptr(50), intptr(150)},
166			3: {false, true, intptr(150), intptr(40)},
167			4: {false, false, nil, nil},
168			5: {true, true, intptr(90), intptr(90)},
169			6: {false, false, intptr(100), intptr(100)},
170		}
171		for height, want := range flips {
172			o, n := oldChain[height-1].Time, newChain[height-1].Time
173			if !sameIntptr(o, want.oldTime) || !sameIntptr(n, want.newTime) {
174				t.Fatalf("height %d times old=%v new=%v, want %v/%v", height, o, n, want.oldTime, want.newTime)
175			}
176			if got := window.contains(o); got != want.oldIn {
177				t.Fatalf("height %d old window membership=%v, want %v", height, got, want.oldIn)
178			}
179			if got := window.contains(n); got != want.newIn {
180				t.Fatalf("height %d new window membership=%v, want %v", height, got, want.newIn)
181			}
182		}
183	
184		index := buildMbTwOldChain(t)
185		dropped, err := index.Reorg(mbTwBranch())
186		if err != nil {
187			t.Fatalf("time-only reorg refused: %v", err)
188		}
189		if want := []int64{2, 3}; !reflect.DeepEqual(dropped, want) {
190			t.Fatalf("dropped=%v, want only the two re-timed heights %v", dropped, want)
191		}
192		if index.Tip != 6 {
193			t.Fatalf("tip=%d, want unchanged 6", index.Tip)
194		}
195		for _, want := range newChain {
196			got, ok := index.Blocks[want.Height]
197			if !ok {
198				t.Fatalf("height %d missing after reorg", want.Height)
199			}
200			if !sameBlock(got, want) {
201				t.Fatalf("height %d stored block=%+v, want %+v", want.Height, got, want)
202			}
203		}
204	}
205	
206	// The core guarantee: a fresh query after the time-only reorg re-judges
207	// MinBlocks qualification entirely by the new times. "old" (down to one
208	// in-window block) must vanish completely; "new" (up to two in-window
209	// blocks) must appear with every in-window occurrence — both h3 duplicates at
210	// their original positions, then h5 — and every page must carry the
211	// whole-range statistics of the NEW chain with the upper height still pinned
212	// at the unchanged tip.
213	func TestQueryTxsMinBlocksReJudgedAfterTimeOnlyReorg(t *testing.T) {
214		index := buildMbTwOldChain(t)
215		query := mbTwQuery()
216	
217		// Before the reorg: "old" qualifies through h1 (real zero at the included
218		// window start) and h2; "new" has only h5, because h3 sits outside the
219		// window, h4's missing timestamp is not a zero, and h6's timestamp equals
220		// the excluded end. The duplicate inside h1 still counts as one block, so
221		// "old" qualifies with exactly two blocks — and once qualified, both
222		// occurrences per block are returned at their original positions.
223		before := collectPages(t, index, query)
224		if len(before) != 2 {
225			t.Fatalf("old-chain pages=%d, want 2 (2/2 over four hits)", len(before))
226		}
227		var beforeHits []TxHit
228		for _, page := range before {
229			if page.TotalMatches != 4 || page.MatchedBlocks != 2 || page.ToHeight != 6 {
230				t.Fatalf("old-chain page stats=%d/%d to=%d, want 4/2 to=6",
231					page.TotalMatches, page.MatchedBlocks, page.ToHeight)
232			}
233			beforeHits = append(beforeHits, page.Hits...)
234		}
235		if !reflect.DeepEqual(beforeHits, mbTwOldHits()) {
236			t.Fatalf("old-chain hits=%v, want %v", beforeHits, mbTwOldHits())
237		}
238	
239		if _, err := index.Reorg(mbTwBranch()); err != nil {
240			t.Fatalf("time-only reorg refused: %v", err)
241		}
242	
243		// After the reorg, from an empty cursor: qualification is decided by the
244		// new times. "old" is down to h1 alone — the duplicate inside h1 must not
245		// count as a second block — so not a single "old" occurrence survives.
246		// "new" qualifies through h3 and h5; h4 (missing time) and h6 (time equal
247		// to the excluded end) still contribute nothing and are never returned.
248		after := collectPages(t, index, query)
249		if len(after) != 2 {
250			t.Fatalf("new-chain pages=%d, want 2 (2/1 over three hits)", len(after))
251		}
252		var afterHits []TxHit
253		for i, page := range after {
254			// Whole-range statistics of the NEW chain on every page: not the
255			// pre-reorg 4/2, and not recomputed from the current page's slice
256			// (page 2 holds a single hit from a single block).
257			if page.TotalMatches != 3 || page.MatchedBlocks != 2 {
258				t.Fatalf("new-chain page %d stats=%d/%d, want the whole-range 3/2 of the new chain",
259					i+1, page.TotalMatches, page.MatchedBlocks)
260			}
261			// The upper bound stays the pinned tip 6: fewer time-filtered results
262			// must not shrink it.
263			if page.ToHeight != 6 {
264				t.Fatalf("new-chain page %d toHeight=%d, want the unchanged pinned tip 6", i+1, page.ToHeight)
265			}
266			afterHits = append(afterHits, page.Hits...)
267		}
268		if !reflect.DeepEqual(afterHits, mbTwNewHits()) {
269			t.Fatalf("new-chain hits=%v, want %v", afterHits, mbTwNewHits())
270		}
271		for _, hit := range afterHits {
272			if hit.TxID == "old" {
273				t.Fatalf("identifier that lost qualification leaked into the new-chain result: %+v", hit)
274			}
275			if hit.Height == 4 || hit.Height == 6 {
276				t.Fatalf("occurrence from a missing-time or end-equal block leaked into the result: %+v", hit)
277			}
278		}
279		// Ordering is by height and in-block position alone; the moved timestamps
280		// (h3 at 40 below h5 at 90) must not reorder anything.
281		requireOrdered(t, afterHits)
282	}
283	
284	// A continuation cursor minted before the reorg pins the old timestamp state
285	// through the range fingerprint. After the reorg — even though every block
286	// hash, parent link, transaction list and the tip height are unchanged — the
287	// old cursor must fail with ErrQueryChanged and a fully zeroed page: the two
288	// chain states' results may never be stitched together.
289	func TestQueryTxsMinBlocksPreReorgCursorDiesAfterTimeOnlyReorg(t *testing.T) {
290		index := buildMbTwOldChain(t)
291		first, err := index.QueryTxs(mbTwQuery())
292		if err != nil {
293			t.Fatal(err)
294		}
295		if first.NextCursor == "" {
296			t.Fatal("first page over 4 matches (page size 2) must carry a cursor")
297		}
298		if !reflect.DeepEqual(first.Hits, mbTwOldHits()[:2]) {
299			t.Fatalf("old first page hits=%v, want %v", first.Hits, mbTwOldHits()[:2])
300		}
301	
302		if _, err := index.Reorg(mbTwBranch()); err != nil {
303			t.Fatalf("time-only reorg refused: %v", err)
304		}
305	
306		query := mbTwQuery()
307		query.Cursor = first.NextCursor
308		page, err := index.QueryTxs(query)
309		requireChangedZeroed(t, page, err)
310	
311		// Restarting from an empty cursor works and describes only the new chain.
312		fresh, err := index.QueryTxs(mbTwQuery())
313		if err != nil {
314			t.Fatal(err)
315		}
316		if fresh.TotalMatches != 3 || fresh.MatchedBlocks != 2 || fresh.ToHeight != 6 {
317			t.Fatalf("fresh page after reorg stats=%d/%d to=%d, want 3/2 to=6",
318				fresh.TotalMatches, fresh.MatchedBlocks, fresh.ToHeight)
319		}
320	}
321	
322	// A branch whose LAST block carries a wrong parent link must reject the whole
323	// reorg: no height is dropped, the pre-reorg hits and statistics are
324	// unchanged, and a cursor minted before the failed reorg keeps paginating the
325	// original chain.
326	func TestQueryTxsMinBlocksReorgWithBadTailParentFailsAndKeepsOldState(t *testing.T) {
327		index := buildMbTwOldChain(t)
328		first, err := index.QueryTxs(mbTwQuery())
329		if err != nil {
330			t.Fatal(err)
331		}
332		if first.NextCursor == "" {
333			t.Fatal("first page over 4 matches (page size 2) must carry a cursor")
334		}
335	
336		broken := mbTwBranch()
337		broken[len(broken)-1].Parent = "not-h5" // the tail no longer links to h5
338		dropped, err := index.Reorg(broken)
339		if err == nil {
340			t.Fatal("branch with a broken tail parent link was accepted")
341		}
342		if dropped != nil {
343			t.Fatalf("rejected reorg reported dropped heights %v, want none", dropped)
344		}
345		if index.Tip != 6 {
346			t.Fatalf("tip=%d after rejected reorg, want 6", index.Tip)
347		}
348	
349		// The original chain still answers exactly as before the failed reorg.
350		fresh := collectPages(t, index, mbTwQuery())
351		var freshHits []TxHit
352		for _, page := range fresh {
353			if page.TotalMatches != 4 || page.MatchedBlocks != 2 || page.ToHeight != 6 {
354				t.Fatalf("page after rejected reorg stats=%d/%d to=%d, want the original 4/2 to=6",
355					page.TotalMatches, page.MatchedBlocks, page.ToHeight)
356			}
357			freshHits = append(freshHits, page.Hits...)
358		}
359		if !reflect.DeepEqual(freshHits, mbTwOldHits()) {
360			t.Fatalf("hits after rejected reorg=%v, want the original %v", freshHits, mbTwOldHits())
361		}
362	
363		// The cursor minted before the failed reorg is still valid and continues
364		// the original chain with the original statistics.
365		query := mbTwQuery()
366		query.Cursor = first.NextCursor
367		rest := collectPages(t, index, query)
368		all := append([]TxHit{}, first.Hits...)
369		for _, page := range rest {
370			if page.TotalMatches != 4 || page.MatchedBlocks != 2 || page.ToHeight != 6 {
371				t.Fatalf("continuation after rejected reorg stats=%d/%d to=%d, want the pinned 4/2 to=6",
372					page.TotalMatches, page.MatchedBlocks, page.ToHeight)
373			}
374			all = append(all, page.Hits...)
375		}
376		if !reflect.DeepEqual(all, mbTwOldHits()) {
377			t.Fatalf("paginated hits across rejected reorg=%v, want %v", all, mbTwOldHits())
378		}
379	}
380	
381	// Qualification is pinned to the whole range, never re-decided per page, and
382	// never left over from the pre-reorg chain: on the new chain the second page
383	// holds a single hit from a single block, yet it must still report the
384	// whole-range 3/2 of the new chain, and a query interleaved with the reorg
385	// must never mix the old qualification (4/2, "old" records) with the new one.
386	func TestQueryTxsMinBlocksNoStaleQualificationAcrossReorg(t *testing.T) {
387		index := buildMbTwOldChain(t)
388	
389		// Drain the old chain fully so its qualification state would be the one
390		// most recently computed, then reorg and re-query from an empty cursor.
391		oldPages := collectPages(t, index, mbTwQuery())
392		var oldHits []TxHit
393		for _, page := range oldPages {
394			oldHits = append(oldHits, page.Hits...)
395		}
396		if !reflect.DeepEqual(oldHits, mbTwOldHits()) {
397			t.Fatalf("old-chain hits=%v, want %v", oldHits, mbTwOldHits())
398		}
399	
400		if _, err := index.Reorg(mbTwBranch()); err != nil {
401			t.Fatal(err)
402		}
403	
404		pages := collectPages(t, index, mbTwQuery())
405		var all []TxHit
406		for _, page := range pages {
407			if page.TotalMatches != 3 || page.MatchedBlocks != 2 || page.ToHeight != 6 {
408				t.Fatalf("stale pre-reorg statistics survived the reorg: %+v", page)
409			}
410			all = append(all, page.Hits...)
411		}
412		if !reflect.DeepEqual(all, mbTwNewHits()) {
413			t.Fatalf("post-reorg hits=%v, want %v", all, mbTwNewHits())
414		}
415	}
