3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// This file is the automated regression for continuing an OrderDesc query
11	// across a snapshot Restore. A Restore replaces the whole main chain at once,
12	// so a cursor minted on the first descending page must be judged purely by the
13	// content of the range that first page pinned:
14	//
15	//   - the cursor binds the full height range fixed on page 1 together with the
16	//     block contents inside it (height, hash, parent, the ordered transaction
17	//     list, and the timestamp's presence and value) — not the snapshot's text
18	//     and not the occurrences the pages have yet to read;
19	//   - a snapshot whose data is identical — object fields reordered, layout
20	//     whitespace added, strings written as equivalent \uXXXX escapes — must
21	//     leave the old cursor usable, and the remaining pages must keep the
22	//     original block hashes and in-block positions, never repeat a record
23	//     already read, never merge duplicate in-block identifiers, and report the
24	//     same fixed-range statistics and timestamp presence/values;
25	//   - a snapshot that changes anything inside the pinned range — including
26	//     only turning an already-read block's missing timestamp into a real zero,
27	//     while its hash, parent, and transactions stay identical and the unread
28	//     transactions are unchanged — must fail the continuation with
29	//     ErrQueryChanged (never ErrInvalidArgument), returning no hits, no cursor,
30	//     and no statistics;
31	//   - a snapshot that changes only block timestamps above the pinned range,
32	//     while the in-range content is byte-identical and the tip still covers
33	//     the range, must leave the old cursor usable with the same remaining
34	//     records and fixed-range statistics.
35	//
36	// The shared fixture is the product-brief descending example: heights 1..3
37	// carry [a,b,a], [a,c], [b,a], the filter is {"a"}, the range is [1,3], and
38	// the page size is 2. Page 1 reads (height 3, position 1) and (height 2,
39	// position 0); page 2 must read (height 1, position 2) and (height 1,
40	// position 0) and then end. Every page reports TotalMatches 4,
41	// MatchedBlocks 3, ToHeight 3.
42	
43	// descRestoreSpecBlocks builds the three-block spec fixture, each block given
44	// the timestamp (nil for a missing time) its caller wants.
45	func descRestoreSpecBlocks(t1, t2, t3 *int64) []Block {
46		return []Block{
47			{Height: 1, Hash: "g1", Parent: "genesis", Txs: []string{"a", "b", "a"}, Time: t1},
48			{Height: 2, Hash: "g2", Parent: "g1", Txs: []string{"a", "c"}, Time: t2},
49			{Height: 3, Hash: "g3", Parent: "g2", Txs: []string{"b", "a"}, Time: t3},
50		}
51	}
52	
53	func buildDescRestoreChain(t *testing.T, blocks []Block) *Index {
54		t.Helper()
55		idx := New()
56		for _, block := range blocks {
57			if err := idx.Append(block); err != nil {
58				t.Fatalf("setup append at height %d: %v", block.Height, err)
59			}
60		}
61		return idx
62	}
