64	// descRestoreQuery is the fixed first-page request of the regression.
65	func descRestoreQuery() TxQuery {
66		return TxQuery{From: 1, To: 3, TxIDs: []string{"a"}, PageSize: 2, Order: OrderDesc}
67	}
