273			t.Fatalf("page1 hits=%v, want %v", page1.Hits, descRestoreWantPage1)
274		}
275		requireDescRestoreRangeStats(t, page1)
276		if page1.NextCursor == "" {
277			t.Fatal("page1 must carry a continuation cursor")
278		}
279	
280		// Version-2 snapshot identical to the current chain except height 2's
281		// timestamp: null (missing) becomes 0 (a real Unix-seconds zero). The
282		// unread height-1 occurrences and every hash/parent/tx list are unchanged.
283		const onlyHeight2Zero = `{"version":2,"tip":3,"blocks":[
284			{"height":1,"hash":"g1","parent":"genesis","txs":["a","b","a"],"timestamp":null},
285			{"height":2,"hash":"g2","parent":"g1","txs":["a","c"],"timestamp":0},
286			{"height":3,"hash":"g3","parent":"g2","txs":["b","a"],"timestamp":null}
287		]}`
288		if err := idx.Restore(strings.NewReader(onlyHeight2Zero)); err != nil {
289			t.Fatalf("restore with a real zero at height 2 rejected: %v", err)
290		}
291		if idx.Tip != 3 {
292			t.Fatalf("tip=%d, want 3 (the restored chain still covers the range)", idx.Tip)
293		}
294		if got := idx.Blocks[2].Time; got == nil || *got != 0 {
295			t.Fatalf("height 2 time=%v, want a pointer to a real zero", got)
296		}
297		if idx.Blocks[1].Time != nil || idx.Blocks[3].Time != nil {
298			t.Fatalf("heights 1 and 3 must still lack timestamps: %v %v",
299				idx.Blocks[1].Time, idx.Blocks[3].Time)
300		}
301	
302		query.Cursor = page1.NextCursor
303		page, err := idx.QueryTxs(query)
304		if !errors.Is(err, ErrQueryChanged) {
305			t.Fatalf("continuation err=%v, want ErrQueryChanged", err)
306		}
307		if errors.Is(err, ErrInvalidArgument) {
308			t.Fatalf("in-range data change reported as ErrInvalidArgument: %v", err)
309		}
310		if !reflect.DeepEqual(page, TxPage{}) {
311			t.Fatalf("changed continuation must return no hits, cursor, or stats, got %+v", page)
312		}
313	
314		// Repeating the stale cursor fails identically: the height-1 occurrences
315		// the old page 2 would have returned are byte-identical data, but they
316		// must never be stitched onto the old first page.
317		page, err = idx.QueryTxs(query)
318		if !errors.Is(err, ErrQueryChanged) || !reflect.DeepEqual(page, TxPage{}) {
319			t.Fatalf("repeated stale cursor: err=%v page=%+v, want ErrQueryChanged and a zeroed page", err, page)
320		}
321	
322		// The index itself is healthy: an empty-cursor first page on the restored
323		// chain succeeds, sees the unchanged transaction occurrences, and still
324		// reports the fixed-range totals over data that did change.
325		fresh, err := idx.QueryTxs(descRestoreQuery())
326		if err != nil {
327			t.Fatalf("fresh first page after restore failed: %v", err)
328		}
329		if !reflect.DeepEqual(fresh.Hits, descRestoreWantPage1) {
330			t.Fatalf("fresh page1 hits=%v, want %v", fresh.Hits, descRestoreWantPage1)
331		}
332		requireDescRestoreRangeStats(t, fresh)
333		if fresh.NextCursor == "" {
334			t.Fatal("fresh first page must carry a continuation cursor")
335		}
336	}
337	
338	// Timestamps changing only ABOVE the pinned range are invisible to the old
339	// cursor: the in-range content stays identical and the restored tip still
340	// covers height 3, so the descending walk continues with the same remaining
341	// records and fixed-range statistics. A matching transaction sitting in an
342	// out-of-range block must not leak in.
343	func TestQueryTxsDescCursorSurvivesOutOfRangeTimestampRestore(t *testing.T) {
344		t4, t5 := int64(100), int64(200)
345		blocks := append(descRestoreSpecBlocks(nil, nil, nil),
346			// Height 4 even carries a matching "a" outside the pinned [1,3] range.
347			Block{Height: 4, Hash: "g4", Parent: "g3", Txs: []string{"a"}, Time: &t4},
348			Block{Height: 5, Hash: "g5", Parent: "g4", Txs: []string{"z"}, Time: &t5},
349		)
350		idx := buildDescRestoreChain(t, blocks)
351	
352		query := descRestoreQuery() // explicitly pins [1,3] despite the tip being 5
353		page1, err := idx.QueryTxs(query)
354		if err != nil {
355			t.Fatalf("first page failed: %v", err)
356		}
357		if !reflect.DeepEqual(page1.Hits, descRestoreWantPage1) {
358			t.Fatalf("page1 hits=%v, want %v", page1.Hits, descRestoreWantPage1)
359		}
360		requireDescRestoreRangeStats(t, page1)
361		if page1.NextCursor == "" {
362			t.Fatal("page1 must carry a continuation cursor")
363		}
364	
365		// Restore keeps heights 1..3 byte-identical (still missing timestamps) and
366		// changes only the timestamps of heights 4 and 5; the tip stays at 5 and
367		// still covers the pinned range.
368		const aboveRangeTimesChanged = `{"version":2,"tip":5,"blocks":[
369			{"height":1,"hash":"g1","parent":"genesis","txs":["a","b","a"],"timestamp":null},
370			{"height":2,"hash":"g2","parent":"g1","txs":["a","c"],"timestamp":null},
371			{"height":3,"hash":"g3","parent":"g2","txs":["b","a"],"timestamp":null},
372			{"height":4,"hash":"g4","parent":"g3","txs":["a"],"timestamp":777},
373			{"height":5,"hash":"g5","parent":"g4","txs":["z"],"timestamp":888}
374		]}`
375		if err := idx.Restore(strings.NewReader(aboveRangeTimesChanged)); err != nil {
376			t.Fatalf("out-of-range timestamp restore rejected: %v", err)
377		}
378		if idx.Tip != 5 {
379			t.Fatalf("tip=%d, want 5 so the pinned range [1,3] stays covered", idx.Tip)
380		}
381		if got := idx.Blocks[4].Time; got == nil || *got != 777 {
382			t.Fatalf("height 4 time=%v, want 777", got)
383		}
384		if got := idx.Blocks[5].Time; got == nil || *got != 888 {
385			t.Fatalf("height 5 time=%v, want 888", got)
386		}
387		if idx.Blocks[1].Time != nil || idx.Blocks[2].Time != nil || idx.Blocks[3].Time != nil {
388			t.Fatal("in-range timestamps must remain missing after the restore")
389		}
390	
391		query.Cursor = page1.NextCursor
392		page2, err := idx.QueryTxs(query)
393		if err != nil {
